import React, { createContext, useContext, useEffect, useMemo, useRef, useState } from "react";
import axios from "axios";
import { API_BASE_URL } from "../config";

const HematrikDataContext = createContext(null);

export function HematrikDataProvider({ children, pollMs = 3000, enabled = true }) {
  const [data, setData] = useState([]);
  const [status, setStatus] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const mountedRef = useRef(true);

  const loadHistory = async () => {
    try {
      setError(null);
      const res = await axios.get(`${API_BASE_URL}/data`);
      if (!mountedRef.current) return;
      setData(Array.isArray(res.data) ? res.data : []);
    } catch (err) {
      if (!mountedRef.current) return;
      setError(err);
    }
  };

  const loadStatus = async () => {
    try {
      const res = await axios.get(`${API_BASE_URL}/status`);
      if (!mountedRef.current) return;
      setStatus(res?.data ?? null);
    } catch (err) {
      // status realtime opsional; biarkan history tetap jalan.
    }
  };

  useEffect(() => {
    mountedRef.current = true;

    if (!enabled) {
      setLoading(false);
      return () => {
        mountedRef.current = false;
      };
    }

    const run = async () => {
      try {
        await Promise.all([loadHistory(), loadStatus()]);
      } finally {
        if (!mountedRef.current) return;
        setLoading(false);
      }
    };

    run();

    const interval = setInterval(run, pollMs);
    return () => {
      mountedRef.current = false;
      clearInterval(interval);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pollMs, enabled]);

  const latest = status ?? (data.length > 0 ? data[0] : null);

  const value = useMemo(
    () => ({
      data,
      latest,
      status,
      loading,
      error,
      reload: async () => {
        await Promise.all([loadHistory(), loadStatus()]);
      }
    }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [data, latest, status, loading, error]
  );

  return <HematrikDataContext.Provider value={value}>{children}</HematrikDataContext.Provider>;
}

export function useHematrikData() {
  const ctx = useContext(HematrikDataContext);
  if (!ctx) {
    throw new Error("useHematrikData must be used within HematrikDataProvider");
  }
  return ctx;
}
